\label{lem:mean}
    For every nonempty $S\subseteq\mathcal N$ and every nonnegative bounded
    compactly supported Borel function $f$ on $V_S$,
    \begin{equation}
        \mathbb E_g
        \sum_{v\in L_S^\circ} f(gv)
        =
        \frac{1}{\operatorname{covol}(L_S)}
        \int_{V_S} f(u)\,du.
        \label{eq:supportwise-siegel}
    \end{equation}
    Equivalently, for a nonnegative bounded compactly supported Borel
    function $F$ on $V$,
    $$
    \mathbb E_g
    \sum_{v\in L}F(gv)
    =
    F(0)
    +
    \sum_{\varnothing\ne S\subseteq\mathcal N}
    \frac{1}{\operatorname{covol}(L_S)}
    \int_{V_S}F(u)\,du.
    $$

\label{lem:supportwise-mean}
    For every nonempty $S\subseteq\mathcal N$,
    \begin{align}
        \mathcal L(S)
        ={}
        \log v_s
        -\frac{s}{d}\log v_d
        +\frac{s}{d}rI
        -rI_{\mathrm{inc}}(S)
        -
        \sum_{n\in S}
        \bigl(rc_n+a\mathbf1_{{n=1}}\bigr)\widetilde y_n.
        \label{eq:finite-support}
    \end{align}

\label{cor:proper-supports}
    Let $\rho>0$ satisfy
    \begin{equation}
        |\log\rho|
        =
        O\left(
            d^{-1}
            +
            \sqrt{\frac{\log d}{r}}
        \right).
        \label{eq:rho-range}
    \end{equation}
    Then, for some $c>0$, the expected number of nonzero vectors in
    $\Lambda_g^*\cap B_\rho$ that vanish in at least one cyclotomic component is at most
    $
    e^{-cr}.
    $

\label{lem:entropy-tensorization}
    For every $S\subseteq X$ we have 
    $$
    \frac{c(S)}2\log\frac{C}{c(S)}
    \le
    \sum_{j=1}^J
    \sum_{u\in X_{-j}}
    c_{-j}(u)\,
    \frac{c_j(S_{j,u})}{2}
    \log\frac{C_j}{c_j(S_{j,u})},
    $$
    where the summand is interpreted as $0$ when
    $S_{j,u}=\varnothing$.

\label{lem:divisor-cube-entropy}
    For every $\mathcal U\subseteq2^{\mathcal P}$ we have 
    \begin{equation*}
        E_{\mathcal P}(\mathcal U)
        \ge
        u(\mathcal U)\log\frac{P}{u(\mathcal U)}.
    \end{equation*}

\label{lem:one-divisor-block}
    Assume \eqref{eq:good-local-block} and that $q$ is sufficiently large.
    Then for every $U\subseteq\mathcal D(q;N)$ we have 
    \begin{equation}
        \frac{c_U}{2}\log\frac{C_{\mathrm{loc}}}{c_U}
        -\frac12W(U,U^c)
        -\sum_{x\in U}\varphi(x)v_x
        \le
        -\delta_0\min\{c_U,C_{\mathrm{loc}}-c_U\},
        \label{eq:one-block-support}
    \end{equation}
    where $
    c_U:=\sum_{x\in U}\varphi(x).
    $
    The first term is interpreted as zero when $c_U=0$.

\label{lem:stochastic-prelim}
    There is an absolute constant $C_{\mathrm{op}}>0$ such that, for
    $t>0$,
    $$
    \Pr_{\mathrm{Br}}\left\{
        \|A_t-a_0\operatorname{Id}\|_{\mathrm{op}}
        >
        C_{\mathrm{op}}\sqrt{dt}
    \right\}
    \le e^{-2d}.
    $$
    Moreover, for every $0\ne x\in\Lambda$ we have 
    $$
    \Pr_{\mathrm{Br}}\left\{
        x \text{ becomes a contact by time }t
    \right\}
    \le
    2\Psi\left(
        \frac{a_0-\|x\|^{-2}}
        {\beta(x)\sqrt t}
    \right).
    $$

\label{prop:stochastic}
    Suppose
    $$
    B_{1-1/d}\cap\Lambda=\{0\}.
    $$
    Then
    $$
    \dim F_{A_t}
    \ge
    q-
    \sum_{x\in\partial E_{A_t}\cap\Lambda}
    \frac1{M_{\operatorname{supp}(x)}},
    $$
    and
    $$
    \mathbb E_{\mathrm{Br}}
    \sum_{x\in\partial E_{A_t}\cap\Lambda}
    \frac1{M_{\operatorname{supp}(x)}}
    \le
    2K_t(\Lambda)+e^{-cd}.
    $$
    Moreover, whenever $dT\le c$,
    \begin{align}
        \mathbb E_{\mathrm{Br}}\log\det A_T
        \le{}&
        -\frac{qT}{2}
        +
        \frac12
        \int_0^T
        \mathbb E_{\mathrm{Br}}
        \sum_{x\in\partial E_{A_t}\cap\Lambda}
        \frac1{M_{\operatorname{supp}(x)}}\,dt
        \notag\\
             &+
             O\left(
                 1+\frac{qT}{d}
                 +qT\sqrt{dT}
                 +qTe^{-2d}
             \right).
             \label{eq:stochastic-det}
    \end{align}

Uniformly for $0<t\le T$ we have 
    \begin{equation*}
        \log\rho_t
        =
        O\left(
            d^{-1}
            +
            \sqrt{\frac{\log d}{r}}
        \right).
        \label{eq:rho-stochastic}
    \end{equation*}
    The estimate for vectors of proper support in \cref{cor:proper-supports} is therefore
    applicable. Since $ 1 / M_{\operatorname{supp}(x)} \le1$ and $0\le\Psi(\cdot)\le1,$ their contribution to $K_t$ is bounded by the number of lattice vectors of proper support in the ball $B_{\rho_t}$. The claimed bound therefore follows
    from \cref{cor:proper-supports}.
